  line([[x0, y], [x1, y]], C.line, 2, 0.6);
  line([[x0, y], [lerp(x0, x1, t / D), y]], C.accent, 2, 0.9);
  V.plan.scenes.forEach((sc, i) => { if (i && sc.chapter) dot(lerp(x0, x1, sc.start / D), y, 2.5, t >= sc.start ? C.accent : C.faint); });
