  const lines = wrap(s, 980, 22, 500);
  const lh = 31, h = lines.length * lh + 18, y = 690 - h;
  const w = Math.max(...lines.map(l => measure(l, 22, 500))) + 40;
  panel(W / 2 - w / 2, y, w, h, { r: 10, fill: "rgba(5,7,12,0.85)", stroke: false });
  lines.forEach((l, j) => text(l, W / 2, y + 31 + j * lh, { size: 22, weight: 500, align: "center", color: "#fff" }));
